import fs from "node:fs";
import path from "node:path";

const ROOT = process.cwd();
const OPENAPI_PATH = path.join(ROOT, "openapi.yaml");
const source = fs.readFileSync(OPENAPI_PATH, "utf8");

const forbidden = [
  "TODO document",
  "Autogenerated OpenAPI stub",
  "Replace this description, request schema, response schema",
];

const matches = [];
for (const marker of forbidden) {
  const lines = source.split(/\r?\n/);
  for (let index = 0; index < lines.length; index += 1) {
    if (lines[index].includes(marker)) {
      matches.push({ marker, line: index + 1, text: lines[index].trim().slice(0, 200) });
    }
  }
}

if (matches.length > 0) {
  console.error(JSON.stringify({
    ok: false,
    error: "openapi_autogenerated_todo_stubs_forbidden",
    message: "Autogenerated OpenAPI TODO stubs must be reviewed and replaced before merge.",
    matches: matches.slice(0, 50),
  }, null, 2));
  process.exit(1);
}

console.log(JSON.stringify({ ok: true, forbidden_markers: forbidden.length }));
